RESET = "\033[0m"
BOLD = "\033[1m"
DIM = "\033[2m"
RED = "\033[31m"
GREEN = "\033[32m"
YELLOW = "\033[33m"
CYAN = "\033[36m"


def terminal_supports_color() -> bool:
    if os.environ.get("NO_COLOR") is not None:
        return False
    return sys.stdout.isatty()


def shorten_path(path: str, max_length: int = 72) -> str:
    if len(path) <= max_length:
        return path
    if max_length < 12:
        return path[:max_length]
    return "..." + path[-(max_length - 3):]


def safe_text(value: Any, default: str = "Unknown") -> str:
    if value is None:
        return default
    text = str(value)
    return text if text else default

def report_base_name(path):
    """Return a safe filename based on the scanned file or directory."""
    path = Path(path)

    if path.is_file():
        name = path.name

        # Preserve dotfiles such as .env (path.stem would otherwise strip
        # the leading dot's "extension", turning ".env" into "").
        if not (name.startswith(".") and name.count(".") == 1):
            name = path.stem
    else:
        name = path.name

    # Remove characters that are invalid in Windows filenames
    name = re.sub(r'[<>:"/\\|?*]', "_", name)

    # Remove problematic trailing/leading filename characters
    name = name.strip(" ._")

    return name or "scan"


def report_filename(path, extension):
    """Generate a report filename based on the scan target."""
    base = report_base_name(path)
    return f"{base}_report.{extension}"

class TerminalUI:
    WIDTH = 78

    def __init__(self) -> None:
        self.use_color = terminal_supports_color()

    def style(self, text: str, *styles: str) -> str:
        if not self.use_color:
            return text
        return "".join(styles) + text + RESET

    def clear(self) -> None:
        # Avoid executing arbitrary terminal input; only fixed commands.
        print("\033[2J\033[H", end="")

    def line(self, character: str = "─") -> None:
        print(character * self.WIDTH)

    def box_top(self) -> None:
        print(self.style("╔" + "═" * (self.WIDTH - 2) + "╗", CYAN))

    def box_bottom(self) -> None:
        print(self.style("╚" + "═" * (self.WIDTH - 2) + "╝", CYAN))

    def title(self, title: str, subtitle: str = "") -> None:
        print()
        self.box_top()
        print(
            self.style(
                "║ " + title.center(self.WIDTH - 4) + " ║",
                CYAN,
                BOLD,
            )
        )
        if subtitle:
            print(
                self.style(
                    "║ " + subtitle.center(self.WIDTH - 4) + " ║",
                    CYAN,
                )
            )
        self.box_bottom()

    def section(self, name: str) -> None:
        print()
        print(self.style(f"  {name}", CYAN, BOLD))
        self.line()

    def success(self, message: str) -> None:
        print(f"  {self.style('✓', GREEN, BOLD)} {message}")

    def warning(self, message: str) -> None:
        print(f"  {self.style('!', YELLOW, BOLD)} {message}")

    def error(self, message: str) -> None:
        print(f"  {self.style('✗', RED, BOLD)} {message}")

    def info(self, message: str) -> None:
        print(f"  {self.style('•', CYAN)} {message}")

    def show_main_menu(self) -> str:
        self.clear()
        self.title(
            "S E C R E T S C A N",
            "Zero-Dependency Local Security Scanner",
        )
        print()
        print(self.style("  SECURITY TOOL", BOLD, CYAN))
        print()
        print("  [1]  Scan a project")
        print("  [2]  Scan a single file")
        print("  [3]  Install Git pre-commit hook")
        print("  [4]  About SecretScan")
        print("  [5]  Exit")
        print()
        return input("  Select an option: ").strip()

    def ask_path(self, prompt: str) -> Path:
        value = input(f"\n  {prompt}: ").strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
            value = value[1:-1]
        return Path(value).expanduser()

    def validate_directory(self, path: Path) -> bool:
        return path.exists() and path.is_dir()

    def validate_file(self, path: Path) -> bool:
        return path.exists() and path.is_file()

    def show_target(self, path: Path, target_type: str) -> None:
        self.section("SCAN TARGET")
        print()
        print(f"  Type       : {target_type}")
        print(f"  Name       : {path.name}")
        print(f"  Location   : {path}")

    def show_project_preview(self, path: Path, max_entries: int = 30) -> None:
        self.section("PROJECT PREVIEW")
        try:
            entries = sorted(
                path.iterdir(),
                key=lambda item: (not item.is_dir(), item.name.lower()),
            )
        except OSError as exc:
            self.error(f"Unable to read project: {exc}")
            return

        if not entries:
            self.warning("The selected directory is empty.")
            return

        shown = entries[:max_entries]
        print()
        for entry in shown:
            print(f"  {'📁' if entry.is_dir() else '📄'}  {entry.name}")

        if len(entries) > len(shown):
            print()
            print(self.style(
                f"  ... and {len(entries) - len(shown)} more entries",
                DIM,
            ))

        print()
        self.info(f"Project entries visible: {len(entries)}")

    def confirm_scan(self, path: Path) -> bool:
        print()
        self.line()
        print(self.style("  Ready to scan:", BOLD))
        print(f"  {path}")
        self.line()
        answer = input("\n  Start security scan? [Y/n]: ").strip().lower()
        return answer in {"", "y", "yes"}

    def show_scan_start(self, path: Path) -> None:
        self.clear()
        self.title("S E C R E T S C A N", "Security analysis in progress")
        print()
        print(self.style("  TARGET", BOLD, CYAN))
        print()
        print(f"  {path}")
        print()
        self.line()
        print()
        print(self.style("  SCANNING...", BOLD, CYAN))
        print()
        print("  Analyzing files and detection rules.")
        print("  Binary, ignored and oversized files are skipped.")
        print()

    @staticmethod
    def _get(finding: Any, field: str, default: Any = None) -> Any:
        if isinstance(finding, dict):
            return finding.get(field, default)
        return getattr(finding, field, default)

    def finding_filepath(self, finding: Any) -> str:
        value = self._get(finding, "filepath")
        if value is None:
            value = self._get(finding, "file")
        return safe_text(value, "Unknown file")

    def finding_line(self, finding: Any) -> str:
        value = self._get(finding, "line_number")
        if value is None:
            value = self._get(finding, "line")
        return safe_text(value, "?")

    def finding_rule(self, finding: Any) -> str:
        value = self._get(finding, "rule_name")
        if value is None:
            value = self._get(finding, "rule")
        return safe_text(value, "Unknown rule")

    def finding_confidence(self, finding: Any) -> str:
        return safe_text(
            self._get(finding, "confidence"),
            "Unknown",
        ).upper()

    def finding_redacted(self, finding: Any) -> str:
        method = getattr(finding, "redacted", None)
        if callable(method):
            try:
                return str(method())
            except Exception:
                return "[REDACTED]"
        value = self._get(finding, "match_redacted")
        return safe_text(value, "[REDACTED]")

    def finding_context(self, finding: Any) -> str:
        return safe_text(
            self._get(finding, "line_context"),
            "[REDACTED CONTEXT UNAVAILABLE]",
        )

    def finding_suggestion(self, finding: Any) -> str:
        return safe_text(
            self._get(finding, "suggestion"),
            "",
        )

    def confidence_icon(self, confidence: str) -> str:
        confidence = confidence.upper()
        if confidence == "HIGH":
            return self.style("●", RED, BOLD)
        if confidence == "MEDIUM":
            return self.style("●", YELLOW, BOLD)
        if confidence == "LOW":
            return self.style("●", GREEN, BOLD)
        return self.style("●", DIM)

    def show_results(
        self,
        path: Path,
        findings: list[Any],
        files_scanned: int,
        elapsed: float,
        show_fix_suggest: bool = False,
        skipped: Any = None,
    ) -> None:
        self.clear()
        self.title("S E C R E T S C A N", "Security scan complete")
        print()
        print(self.style("  TARGET", BOLD, CYAN))
        print()
        print(f"  {path}")
        print()
        self.line()

        counts = {"HIGH": 0, "MEDIUM": 0, "LOW": 0, "UNKNOWN": 0}
        for finding in findings:
            confidence = self.finding_confidence(finding)
            counts[confidence if confidence in counts else "UNKNOWN"] += 1

        print()
        print(self.style("  SCAN SUMMARY", BOLD, CYAN))
        print()
        print(f"  {self.style('●', RED)} HIGH confidence   : {counts['HIGH']}")
        print(f"  {self.style('●', YELLOW)} MEDIUM confidence : {counts['MEDIUM']}")
        print(f"  {self.style('●', GREEN)} LOW confidence    : {counts['LOW']}")
        print(f"  {self.style('●', DIM)} UNKNOWN           : {counts['UNKNOWN']}")
        print()
        print(f"  Files scanned : {files_scanned}")
        print(f"  Findings      : {len(findings)}")
        print(f"  Scan time     : {elapsed:.4f} seconds")

        skip_total = getattr(skipped, "total", None)
        if skip_total is None and isinstance(skipped, dict):
            skip_total = sum(skipped.get("counts", {}).values())
        if skip_total:
            skip_counts = getattr(skipped, "counts", None)
            if skip_counts is None and isinstance(skipped, dict):
                skip_counts = skipped.get("counts", {})
            breakdown = ", ".join(
                f"{reason}={count}"
                for reason, count in sorted((skip_counts or {}).items())
            )
            print(f"  Files skipped : {skip_total} ({breakdown})")

        print()

        if not findings:
            self.line()
            print()
            print(self.style("  ✓ NO POTENTIAL SECRETS DETECTED", GREEN, BOLD))
            print()
            self.info("No configured detections were reported.")
            return

        self.line()
        print()
        print(self.style("  FINDINGS", BOLD, CYAN))
        print()

        for index, finding in enumerate(findings, start=1):
            confidence = self.finding_confidence(finding)
            rule = self.finding_rule(finding)
            filepath = self.finding_filepath(finding)
            line = self.finding_line(finding)

            print(
                f"  {index:>3}. "
                f"{self.confidence_icon(confidence)} "
                f"{confidence:<7} "
                f"{rule}"
            )
            print(f"       {shorten_path(filepath, 54)}:{line}")
            print(f"       Match: {self.finding_redacted(finding)}")
            print(f"       Context: {self.finding_context(finding)}")
            if show_fix_suggest:
                suggestion = self.finding_suggestion(finding)
                if suggestion:
                    print(f"       Suggestion: {suggestion}")
            print()

        self.line()

        if counts["HIGH"]:
            self.warning("HIGH confidence findings will return exit code 1.")
        else:
            self.info("Only warning-level findings were detected; exit code 0.")

    def show_finding_details(
        self,
        finding: Any,
        index: int,
        show_fix_suggest: bool = False,
    ) -> None:
        self.clear()
        self.title("FINDING DETAILS", f"Finding #{index}")

        confidence = self.finding_confidence(finding)
        print()
        print(self.style("  DETECTION INFORMATION", BOLD, CYAN))
        print()
        print(f"  Confidence : {self.confidence_icon(confidence)} {confidence}")
        print(f"  Rule       : {self.finding_rule(finding)}")
        print(f"  File       : {self.finding_filepath(finding)}")
        print(f"  Line       : {self.finding_line(finding)}")
        print()

        self.line()
        print()
        print(self.style("  REDACTED DETECTION", BOLD, CYAN))
        print()
        print(f"  Match   : {self.finding_redacted(finding)}")
        print(f"  Context : {self.finding_context(finding)}")
        print()
        self.warning("The potential secret value is redacted for safety.")

        if show_fix_suggest:
            suggestion = self.finding_suggestion(finding)
            if suggestion:
                print()
                print(self.style("  SUGGESTED FIX", BOLD, CYAN))
                print()
                print(f"  {suggestion}")

        print()
        self.line()
        print()
        self.info("Review the indicated file and line before committing or publishing.")
        print()
        input("  Press Enter to return to findings...")

    def choose_finding(self, findings: list[Any]) -> int | None:
        if not findings:
            return None

        print()
        print(self.style("  Enter a finding number to inspect.", DIM))
        print(self.style("  Enter B to go back.", DIM))
        value = input("\n  Selection: ").strip().lower()

        if value in {"", "b", "back"}:
            return None

        try:
            number = int(value)
        except ValueError:
            self.warning("Please enter a valid number.")
            self.pause()
            return None

        index = number - 1
        if not 0 <= index < len(findings):
            self.warning("That finding number does not exist.")
            self.pause()
            return None

        return index

    def export_json(
        self,
        path: Path,
        findings: list[Any],
        files_scanned: int,
        elapsed: float,
        skipped: Any = None,
    ) -> None:
        output_path = path.parent / report_filename(path, "json")

        try:
            write_json_report(
                findings,
                files_scanned,
                elapsed,
                output_path,
                skipped=skipped,
            )
            self.success(f"JSON report saved to: {output_path}")
        except OSError as exc:
            self.error(f"Could not save JSON report: {exc}")

        self.pause()


    def export_html(
        self,
        path: Path,
        findings: list[Any],
        files_scanned: int,
        elapsed: float,
        skipped: Any = None,
    ) -> None:
        output_path = path.parent / report_filename(path, "html")

        try:
            write_html_report(
                findings,
                files_scanned,
                elapsed,
                output_path,
                str(path),
                skipped=skipped,
            )
            self.success(f"HTML report saved to: {output_path}")
        except OSError as exc:
            self.error(f"Could not save HTML report: {exc}")

        self.pause()

    def findings_loop(
        self,
        path: Path,
        findings: list[Any],
        files_scanned: int,
        elapsed: float,
        show_fix_suggest: bool = False,
        skipped: Any = None,
    ) -> None:
        while True:
            self.show_results(
                path,
                findings,
                files_scanned,
                elapsed,
                show_fix_suggest=show_fix_suggest,
                skipped=skipped,
            )

            print()
            self.line()
            print()
            print(self.style("  ACTIONS", BOLD, CYAN))
            print()
            print("  Enter a finding number to inspect it.")
            print("  [J] Export JSON report")
            print("  [H] Export HTML report")
            print("  [B] Back")
            print()

            value = input("  Selection: ").strip().lower()

            if value in {"b", "back", ""}:
                return

            if value in {"j", "json"}:
                self.export_json(
                    path,
                    findings,
                    files_scanned,
                    elapsed,
                    skipped=skipped,
                )
                continue

            if value in {"h", "html"}:
                self.export_html(
                    path,
                    findings,
                    files_scanned,
                    elapsed,
                    skipped=skipped,
                )
                continue

            try:
                number = int(value)
            except ValueError:
                self.warning(
                    "Please enter a finding number, J, H, or B."
                )
                self.pause()
                continue

            index = number - 1

            if not 0 <= index < len(findings):
                self.warning("That finding number does not exist.")
                self.pause()
                continue

            self.show_finding_details(
                findings[index],
                index + 1,
                show_fix_suggest=show_fix_suggest,
            )

    def show_about(self) -> None:
        self.clear()
        self.title("ABOUT SECRETSCAN", "Zero-Dependency Security Scanner")
        print()
        print("  SecretScan is a local developer-security tool")
        print("  designed to detect potential hardcoded secrets")
        print("  before they are committed or published.")
        print()
        print(self.style("  FEATURES", BOLD, CYAN))
        print()
        for item in (
            "Local recursive scanning",
            "Pattern and entropy detection",
            "Redacted values and redacted line context",
            ".gitignore and default directory filtering",
            ".bash_history / .zsh_history scanning",
            "Inline secretscan-ignore support",
            "Severity-aware exit codes",
            "Baseline support",
            "Fix suggestions",
            "JSON and HTML reports",
            "Git pre-commit integration",
            "TOML configuration",
            "Python standard library only",
            "No network calls",
        ):
            print(f"  • {item}")
        print()
        self.line()
        print()
        self.warning("A finding is not proof that a value is active.")
        print()
        self.pause()

    def pause(self) -> None:
        input("\n  Press Enter to continue...")


def validate_target(path: Path, expect_directory: bool = True) -> bool:
    if not path.exists():
        return False
    return path.is_dir() if expect_directory else path.is_file()

# ============================================================================
# --- secretscan.py (entrypoint) ------------------------------------------
# ============================================================================

# The hook is a plain POSIX shell script executed BY GIT as part of its
# own commit machinery — this is what every pre-commit hook does, by
# definition, and is not this program invoking an external tool on its
# own initiative. Crucially, secretscan.py itself never calls out to
# git: the hook asks git which files are staged, then passes that
# filename list as ordinary positional arguments to `scan`, so all
# actual secret detection still runs through pure standard-library
# code with zero knowledge of git at all. See STDLIB.md.
#
# Filenames are never captured into a shell variable and re-expanded
# ($STAGED_FILES) — POSIX shell word-splits unquoted expansions on
# whitespace, so a staged path containing a space would be sliced into
# bogus fragments, and a filename starting with "-" (e.g.
# "-secrets.env") could be parsed as a flag instead of a path. Command
# substitution is also unsafe here for a subtler reason: shell
# variables can't reliably hold embedded NUL bytes, so even a
# NUL-delimited `git diff -z` output gets silently truncated if
# assigned to a variable first.
#
# Instead: (1) a `git diff --quiet` probe decides whether there's
# anything staged, with no filenames touched at all, and (2) the
# actual filenames are streamed straight from `git diff -z` (NUL
# delimited, so any character including spaces/newlines is safe)
# through `xargs -0` directly into the scanner, with `--` before the
# path list so argparse always treats every argument after it as a
# path, never as an option.
PRE_COMMIT_HOOK_TEMPLATE = """#!/bin/sh
# Installed by SecretScan — blocks commits containing HIGH-confidence findings.
SCANNER={scanner_path}
PYTHON={python_executable}

# Nothing staged (of the types we care about)? Nothing to scan.
if git diff --cached --quiet --diff-filter=ACMR; then
    exit 0
fi

if [ -x "$PYTHON" ]; then
    RUNNER="$PYTHON"
else
    RUNNER=python3
fi

# -z / -0: NUL-delimited end to end, so spaces, quotes and newlines in
# a staged filename can never be mis-split. "--" stops argparse from
# treating a filename that starts with "-" as an option.
git diff --cached --name-only --diff-filter=ACMR -z \\
    | xargs -0 "$RUNNER" "$SCANNER" scan --
exit $?
"""


def _load_baseline(path):
    if not os.path.isfile(path):
        return {"version": 1, "fingerprints": []}

    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
        if isinstance(data, dict) and isinstance(data.get("fingerprints"), list):
            return data
    except (OSError, ValueError):
        pass

    return {"version": 1, "fingerprints": []}


def _write_baseline(path, findings):
    payload = {
        "version": 1,
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "fingerprints": sorted(
            {
                finding.fingerprint
                for finding in findings
                if finding.fingerprint
            }
        ),
    }
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)
        handle.write("\n")


def _resolve_config_path(default_root, configured):
    """Resolve a possibly-relative config/report/baseline path.

    Relative paths resolve against the current working directory
    (where the user ran the command from), not against whatever
    file/directory happens to be the scan target — otherwise scanning
    a single file elsewhere on disk would scatter baseline/report
    files into that file's directory instead of the user's project.
    """
    if os.path.isabs(configured):
        return configured
    return os.path.join(os.getcwd(), configured)


def _report_base_name(scan_paths):
    """Return a safe report filename base derived from the scan target(s)."""
    from pathlib import Path
    import re

    if len(scan_paths) == 1:
        path = Path(scan_paths[0])
        name = path.stem if path.is_file() else path.name
    else:
        name = "multi_target_scan"

    name = re.sub(r'[<>:"/\\|?*]', "_", name)
    name = name.strip(" ._")

    return name or "scan"


def cmd_scan(args):
    start = time.perf_counter()
    targets = [os.path.abspath(p) for p in args.paths]

    missing = [p for p in targets if not os.path.exists(p)]
    if missing:
        for p in missing:
            print(f"Error: path does not exist: {p}", file=sys.stderr)
        return 2

    # Config is loaded from the first target's directory (or the
    # target itself, if it's a directory) — good enough for the
    # common case of scanning one project.
    first = targets[0]
    config = load_config(first if os.path.isdir(first) else os.path.dirname(first))

    configure_entropy(config.entropy_threshold, config.min_entropy_len)
    findings, files_scanned, skipped = scan_path(
        targets,
        pattern_finder=find_pattern_matches,
        entropy_finder=find_entropy_matches,
        extra_ignore_dirs=config.ignore_dirs,
        max_file_size_bytes=int(config.max_file_size_mb * 1024 * 1024),
        include_history=args.include_shell_history,
    )

    baseline_path = _resolve_config_path(first, args.baseline or config.baseline_file)
    baseline = _load_baseline(baseline_path)

    if args.update_baseline:
        _write_baseline(baseline_path, findings)
        # Updating the baseline explicitly accepts the current findings.
        findings = []
    else:
        findings = apply_baseline(findings, baseline)

    elapsed = time.perf_counter() - start
    report_base = _report_base_name(args.paths)

    if args.html_report:
        html_path = _resolve_config_path(first, args.html_report)
        write_html_report(
            findings, files_scanned, elapsed, html_path, ", ".join(args.paths),
            skipped=skipped,
        )
        print(f"HTML report written to: {html_path}")

    if args.json:
        json_path = _resolve_config_path(first, f"{report_base}_report.json")
        write_json_report(findings, files_scanned, elapsed, json_path, skipped=skipped)
        print(f"JSON report written to: {json_path}")
        print(format_json(findings, files_scanned, elapsed, skipped=skipped))
    else:
        print(
            format_human(
                findings,
                files_scanned,
                elapsed,
                show_fix_suggest=args.fix_suggest,
                skipped=skipped,
            )
        )

    # HIGH blocks; MEDIUM/LOW only warn.
    return 1 if any(f.confidence == "HIGH" for f in findings) else 0


def scan_target_with_ui(
    ui: TerminalUI,
    path: str,
    fix_suggest: bool = False,
) -> None:
    from pathlib import Path

    target = os.path.abspath(path)

    if not os.path.exists(target):
        ui.error(f"Path does not exist: {target}")
        ui.pause()
        return

    ui.show_scan_start(target)
    start = time.perf_counter()

    config = load_config(target if os.path.isdir(target) else os.path.dirname(target))
    configure_entropy(config.entropy_threshold, config.min_entropy_len)

    try:
        findings, files_scanned, skipped = scan_path(
            target,
            pattern_finder=find_pattern_matches,
            entropy_finder=find_entropy_matches,
            extra_ignore_dirs=config.ignore_dirs,
            max_file_size_bytes=int(config.max_file_size_mb * 1024 * 1024),
        )
    except (OSError, UnicodeError) as exc:
        ui.error(f"Scan failed: {exc}")
        ui.pause()
        return
    except Exception as exc:
        ui.error(f"Unexpected scanner error: {exc}")
        ui.pause()
        return

    elapsed = time.perf_counter() - start
    ui.findings_loop(
        Path(target),
        findings,
        files_scanned,
        elapsed,
        show_fix_suggest=fix_suggest,
        skipped=skipped,
    )


def cmd_ui(args):
    ui = TerminalUI()

    while True:
        choice = ui.show_main_menu()

        if choice == "1":
            path = ui.ask_path("Project path")
            if not validate_target(path, expect_directory=True):
                ui.error("That path is not a valid directory.")
                ui.pause()
                continue

            ui.clear()
            ui.title("PROJECT READY", "Review target before scanning")
            ui.show_target(path, "Directory")
            ui.show_project_preview(path)

            if ui.confirm_scan(path):
                scan_target_with_ui(ui, str(path), fix_suggest=args.fix_suggest)

        elif choice == "2":
            path = ui.ask_path("File path")
            if not validate_target(path, expect_directory=False):
                ui.error("That path is not a valid file.")
                ui.pause()
                continue

            ui.clear()
            ui.title("FILE READY", "Review target before scanning")
            ui.show_target(path, "File")

            if ui.confirm_scan(path):
                scan_target_with_ui(ui, str(path), fix_suggest=args.fix_suggest)

        elif choice == "3":
            ui.clear()
            ui.title("GIT PRE-COMMIT HOOK", "Protect commits from likely secrets")
            path = ui.ask_path("Git repository path")

            result = cmd_install_hook(argparse.Namespace(path=str(path)))

            if result == 0:
                ui.success("Git pre-commit hook installed successfully.")
            ui.pause()

        elif choice == "4":
            ui.show_about()

        elif choice == "5":
            ui.clear()
            ui.title("SECRETSCAN", "Goodbye")
            print()
            ui.success("Exiting.")
            print()
            return 0

        else:
            ui.warning("Invalid option. Choose 1, 2, 3, 4, or 5.")
            ui.pause()


def cmd_install_hook(args):
    repo_path = os.path.abspath(args.path)
    git_dir = os.path.join(repo_path, ".git")

    if not os.path.isdir(git_dir):
        print(
            f"Error: {repo_path} is not a git repository (.git not found).",
            file=sys.stderr,
        )
        return 1

    hooks_dir = os.path.join(git_dir, "hooks")
    os.makedirs(hooks_dir, exist_ok=True)

    hook_path = os.path.join(hooks_dir, "pre-commit")

    if os.path.exists(hook_path) and not getattr(args, "force", False):
        print(
            f"Error: {hook_path} already exists. Re-run with --force to overwrite it.",
            file=sys.stderr,
        )
        return 1

    scanner_path = os.path.abspath(__file__)
    python_executable = os.path.abspath(sys.executable)

    content = PRE_COMMIT_HOOK_TEMPLATE.format(
        scanner_path=scanner_path,
        python_executable=python_executable,
    )

    with open(hook_path, "w", encoding="utf-8", newline="\n") as handle:
        handle.write(content)

    try:
        os.chmod(hook_path, 0o755)
    except OSError:
        pass

    print(f"Installed pre-commit hook at {hook_path}")
    return 0


def build_parser():
    parser = argparse.ArgumentParser(
        prog="secretscan",
        description="Zero-dependency local secrets leak scanner.",
    )

    subparsers = parser.add_subparsers(dest="command", required=True)

    scan_p = subparsers.add_parser("scan", help="Scan one or more files/directories for secrets.")
    scan_p.add_argument("paths", nargs="+", help="File(s) or directory(ies) to scan.")
    scan_p.add_argument("--json", action="store_true", help="Output machine-readable JSON.")
    scan_p.add_argument("--fix-suggest", action="store_true", help="Show remediation suggestions.")
    scan_p.add_argument("--baseline", help="Path to baseline JSON file.")
    scan_p.add_argument("--update-baseline", action="store_true",
                        help="Accept current findings into the baseline.")
    scan_p.add_argument("--html-report", metavar="PATH", help="Write an HTML report to PATH.")
    scan_p.add_argument("--include-shell-history", action="store_true",
                        help="Also scan common shell history files (off by default).")
    scan_p.set_defaults(func=cmd_scan)

    ui_p = subparsers.add_parser("ui", help="Launch the interactive terminal interface.")
    ui_p.add_argument("--fix-suggest", action="store_true",
                      help="Show remediation suggestions in the UI.")
    ui_p.set_defaults(func=cmd_ui)

    hook_p = subparsers.add_parser("install-hook", help="Install as a Git pre-commit hook.")
    hook_p.add_argument("--path", default=".", help="Path to the Git repo root (default: .)")
    hook_p.add_argument("--force", action="store_true", help="Overwrite an existing hook.")
    hook_p.set_defaults(func=cmd_install_hook)

    return parser


def main():
    parser = build_parser()
    args = parser.parse_args()
    sys.exit(args.func(args))


if __name__ == "__main__":
    main()
